rpg-hud.css:
@keyframes bootSheen { 
  100% { transform: translateX(100%); }
}
@keyframes bootTipIn { 
  0% { opacity: 0; transform: translateY(5px); }
  100% { opacity: 1; transform: none; }
}
:root { --slate: #1b2030; --slate-2: #252c41; --slate-3: #111522; --chalk: #e9dfc4; --copper: #48b39c; --rune: #e2a93c; --blood: #d24a41; --edge: rgba(233,223,196,.22); --ink: var(--chalk); --ink-2: rgba(233,223,196,.82); --ink-3: rgba(233,223,196,.62); --ink-4: rgba(233,223,196,.42); --ink-5: rgba(233,223,196,.24); --wayfind: #73e5ff; --hearth: #f08a36; --arcane: #aa7be8; --gain: #1eff00; --loss: #ff4d4d; --rar-0: #9aa3b2; --rar-1: #e9dfc4; --rar-2: #4ad07a; --rar-3: #4aa3ff; --rar-4: #c76bff; --rar-5: #ff9a3c; --surface: linear-gradient(180deg,rgba(37,44,65,.94),rgba(19,23,36,.96)); --surface-well: linear-gradient(180deg,rgba(14,18,30,.98),rgba(8,11,19,.99)); --surface-raised: linear-gradient(180deg,#242b3f,#151a28); --surface-hot: linear-gradient(180deg,#e2c07c,#c99a3f); --r-1: 2px; --r-2: 3px; --r-3: 4px; --r-4: 6px; --r-5: 8px; --s-1: 4px; --s-2: 6px; --s-3: 8px; --s-4: 10px; --s-5: 12px; --s-6: 16px; --s-7: 20px; --s-8: 26px; --bevel: inset 0 0 0 1px rgba(233,223,196,.14); --bevel-hot: inset 0 0 0 1px rgba(233,223,196,.32); --e-1: var(--bevel),0 2px 0 rgba(0,0,0,.45),0 4px 10px rgba(0,0,0,.35); --e-2: var(--bevel),0 3px 0 rgba(0,0,0,.5),0 10px 26px rgba(0,0,0,.5); --e-3: var(--bevel),inset 0 12px 22px rgba(0,0,0,.35), 0 5px 0 rgba(0,0,0,.55),0 20px 48px rgba(0,0,0,.6); --e-tip: 0 10px 30px rgba(0,0,0,.7),inset 0 0 0 1px rgba(255,255,255,.04); --ease: cubic-bezier(.2,.8,.3,1); --ease-out: cubic-bezier(.2,0,0,1); --t-press: .08s; --t-hover: .12s; --t-flip: .18s; --t-panel: .32s; --t-stagger: .08s; --bar-sheen: linear-gradient(180deg,rgba(255,255,255,.32) 0%,rgba(255,255,255,.08) 42%,transparent 70%); --bar-well: #070a12; --font-serif: "Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif; --font-mono: ui-monospace,"SF Mono",Menlo,Consolas,monospace; }
* { box-sizing: border-box; }
canvas { display: block; }
.mono { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
.eyebrow { font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace; font-size: 9px; letter-spacing: 0.26em; text-transform: uppercase; color: rgba(233, 223, 196, 0.55); }
.tnum { font-variant-numeric: tabular-nums; }
.ring:focus-visible, button:focus-visible, [tabindex]:focus-visible { outline: 2px solid var(--copper); outline-offset: 2px; }
@keyframes beatIn { 
  0% { opacity: 0; transform: translateY(10px); filter: blur(4px); }
  100% { opacity: 1; transform: translateY(0px); filter: blur(0px); }
}
@media (prefers-reduced-motion: reduce) {@keyframes beatIn { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}}
#hud { position: fixed; inset: 0px; pointer-events: none; z-index: 5; --loot-gutter: 14px; --map-lens: 126px; --map-bezel: 18px; --map-rail: calc(var(--map-lens) + var(--map-bezel)); --map-lift: 14px; --loot-gap: 12px; --loot-right: calc(var(--loot-gutter) + var(--map-rail) + var(--loot-gap)); --loot-bottom: var(--map-lift); --loot-max-w: min(280px,calc(100vw - var(--loot-right) - 132px)); }
#hud > * { position: absolute; }
#speedLines { left: 0px; top: 0px; }
.unit { display: flex; gap: 9px; align-items: flex-start; padding: 8px; width: 268px; background: linear-gradient(rgba(40, 48, 70, 0.96), rgba(16, 20, 32, 0.98)); border: 1px solid rgba(0, 0, 0, 0.85); border-radius: var(--r-4); box-shadow: var(--bevel),inset 0 1px #ffffff0f,inset 0 14px 24px #0006,0 3px #00000080,0 12px 28px #0000008c; }
#playerFrame { top: 14px; left: 14px; }
#targetFrame { top: 14px; left: 298px; opacity: 0; transform: translateY(-4px); transition: opacity .2s var(--ease),transform .2s var(--ease); }
.portrait { width: 58px; height: 58px; flex: 0 0 58px; border-radius: var(--r-2); overflow: hidden; border: 1px solid rgba(0, 0, 0, 0.8); background: rgb(16, 20, 31); outline: rgba(255, 255, 255, 0.08) solid 1px; outline-offset: -2px; box-shadow: rgba(226, 169, 60, 0.4) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.5) 0px -10px 16px inset, rgba(226, 169, 60, 0.35) 0px 0px 16px -6px; }
.portrait.tgt { box-shadow: rgba(210, 74, 65, 0.45) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.5) 0px -10px 16px inset, rgba(210, 74, 65, 0.4) 0px 0px 16px -6px; outline-color: rgba(255, 255, 255, 0.08); }
.portrait canvas { width: 100%; height: 100%; display: block; image-rendering: pixelated; }
.ubody { flex: 1 1 auto; min-width: 0px; }
.urow { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 4px; }
.uname { font-size: 13px; letter-spacing: 0.02em; text-shadow: rgba(0, 0, 0, 0.7) 0px 2px 0px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ulvl { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 10px; color: var(--rune); border: 1px solid rgba(226, 169, 60, 0.45); border-radius: 2px; padding: 0px 4px; margin-left: 6px; flex: 0 0 auto; box-shadow: rgba(226, 169, 60, 0.45) 0px 0px 8px -2px; font-variant-numeric: tabular-nums; }
.bar { position: relative; height: 15px; margin-bottom: 4px; background: var(--bar-well); border: 1px solid rgba(0, 0, 0, 0.85); border-radius: var(--r-1); overflow: hidden; box-shadow: rgba(233, 223, 196, 0.07) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.55) 0px 2px 4px inset; }
.bar .fill { position: absolute; inset: 0px; width: 100%; transform-origin: left center; transition: width 0.16s cubic-bezier(0.2, 0.8, 0.3, 1); }
.bar .fill::after { content: ""; position: absolute; left: 0px; right: 0px; top: 0px; height: 48%; background: var(--bar-sheen); pointer-events: none; }
.bar.hp .fill { background: linear-gradient(rgb(240, 106, 92), rgb(196, 51, 42) 55%, rgb(138, 22, 16)); }
.bar.res .fill { background: linear-gradient(rgb(111, 224, 196), rgb(47, 143, 125) 55%, rgb(30, 95, 84)); }
.bar.posture { height: 8px; display: none; margin-top: -1px; margin-bottom: 4px; background: linear-gradient(rgb(23, 24, 32), rgb(11, 12, 17)); }
.bar.posture .fill { background: linear-gradient(rgb(255, 227, 160), rgb(220, 168, 62) 55%, rgb(151, 99, 30)); }
.postureLabel { position: absolute; z-index: 1; right: 3px; top: -1px; font-size: 6px; letter-spacing: 0.14em; color: rgba(255, 247, 221, 0.76); text-shadow: rgb(0, 0, 0) 0px 1px 2px; }
@keyframes postureBreakPulse { 
  100% { filter: brightness(1.65); transform: scaleY(1.25); }
}
.bar .chip { position: absolute; top: 0px; bottom: 0px; background: rgba(255, 214, 190, 0.55); transition: width 0.45s ease-out 0.18s; }
.bar .btext { position: absolute; inset: 0px; display: flex; align-items: center; justify-content: center; font-size: 10px; letter-spacing: 0.04em; color: rgb(255, 255, 255); z-index: 1; text-shadow: rgba(0, 0, 0, 0.95) 0px 1px 2px, rgba(0, 0, 0, 0.6) 0px 0px 6px; font-variant-numeric: tabular-nums; }
.bar.res { height: 11px; }
.bar.focus { height: 10px; display: none; }
.bar.focus .fill { background: linear-gradient(rgb(212, 174, 248), rgb(127, 79, 196) 55%, rgb(92, 47, 156)); }
.bar.charge { height: 9px; display: none; }
.bar.charge .fill { background: linear-gradient(rgb(154, 245, 200), rgb(58, 163, 122) 55%, rgb(35, 122, 88)); }
#relics { display: flex; gap: 6px; margin-top: 6px; align-items: center; }
.relic { width: 11px; height: 11px; background: rgb(11, 14, 23); border: 1px solid rgba(0, 0, 0, 0.7); box-shadow: rgba(233, 223, 196, 0.12) 0px 0px 0px 1px inset; transform: rotate(45deg); transition-property: background, box-shadow; transition-duration: 0.3s; }
#tide { width: 104px; height: 4px; margin-top: 6px; background: rgb(11, 14, 23); border: 1px solid rgba(0, 0, 0, 0.7); box-shadow: rgba(233, 223, 196, 0.1) 0px 0px 0px 1px inset; overflow: hidden; }
#tideFill { height: 100%; width: 0px; background: linear-gradient(90deg, rgb(92, 42, 82), rgb(139, 58, 94)); transition: width 1.2s, background 0.8s; }
#buffStrip { display: flex; gap: 5px; margin-top: 6px; align-items: center; flex-wrap: wrap; }
@keyframes buffFade { 
  0% { opacity: 1; }
  100% { opacity: 0.45; }
}
#tDebuffs { display: flex; gap: 4px; margin-top: 4px; align-items: center; flex-wrap: wrap; }
#tDebuffs:empty { display: none; }
#partyDock { position: absolute; z-index: 18; left: 0px; top: calc(100% + 6px); width: 100%; display: grid; gap: 4px; pointer-events: auto; }
#partyDock[hidden] { display: none; }
@keyframes partyThreat { 
  0% { box-shadow: rgba(255, 90, 70, 0.1) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.35) 0px 3px 8px; }
  100% { box-shadow: rgba(255, 70, 50, 0.2) 0px 0px 12px inset, rgba(255, 70, 50, 0.2) 0px 0px 13px; }
}
#quest { top: 14px; right: 14px; width: auto; max-width: min(240px, 42vw); display: flex; flex-direction: row; align-items: flex-start; gap: 10px; padding: 8px 10px 8px 8px; text-align: left; cursor: pointer; pointer-events: auto; color: inherit; font: inherit; border: 0px; border-radius: var(--r-3); background: rgba(8, 11, 18, 0.42); box-shadow: rgba(233, 223, 196, 0.1) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.28) 0px 6px 18px; transition-property: transform, box-shadow, background-color, opacity; transition-duration: var(--t-hover); transition-timing-function: var(--ease); }
#quest:hover { transform: translateY(-1px); background: rgba(8, 11, 18, 0.58); box-shadow: rgba(226, 169, 60, 0.28) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.35) 0px 8px 22px; }
#quest:active { transform: scale(0.98); }
#quest:focus-visible { outline: 2px solid var(--copper); outline-offset: 3px; }
.questMark { flex: 0 0 12px; width: 12px; height: 12px; margin-top: 5px; transform: rotate(45deg); border: 1px solid rgba(226, 169, 60, 0.85); background: rgba(226, 169, 60, 0.28); box-shadow: rgba(226, 169, 60, 0.45) 0px 0px 10px; }
.questBody { min-width: 0px; display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding-bottom: 2px; }
#questTag { color: rgba(226, 169, 60, 0.78); letter-spacing: 0.2em; font-size: 9px; margin: 0px; }
#questLine { font-size: 13px; line-height: 1.3; margin: 0px; text-wrap: pretty; text-shadow: rgba(0, 0, 0, 0.75) 0px 1px 2px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
#distLine { margin: 0px; font-size: 10px; letter-spacing: 0.14em; color: rgba(233, 223, 196, 0.55); }
#distLine:empty { display: none; }
#questOpen { margin: 4px 0px 0px; opacity: 0; color: var(--rune); transition-property: opacity; transition-duration: var(--t-hover); }
#quest:hover #questOpen, #quest:focus-visible #questOpen { opacity: 1; }
#questOpen b { font-weight: 400; border: 1px solid rgba(226, 169, 60, 0.45); padding: 0px 4px; margin-right: 4px; border-radius: var(--r-1); }
@keyframes questFresh { 
  0% { transform: rotate(45deg) scale(0.6); box-shadow: rgba(226, 169, 60, 0) 0px 0px; }
  40% { transform: rotate(45deg) scale(1.25); box-shadow: rgba(226, 169, 60, 0.8) 0px 0px 16px; }
  100% { transform: rotate(45deg) scale(1); box-shadow: rgba(226, 169, 60, 0.45) 0px 0px 10px; }
}
#bossbar { left: 50%; top: 74px; transform: translate(-50%); width: min(58vw, 560px); opacity: 0; transition: opacity .4s var(--ease); text-align: center; filter: drop-shadow(rgba(0, 0, 0, 0.55) 0px 8px 24px); }
#bossName { font-size: 14px; letter-spacing: 0.1em; margin-bottom: 6px; text-transform: uppercase; text-shadow: rgba(0, 0, 0, 0.9) 0px 2px 3px, rgba(226, 169, 60, 0.25) 0px 0px 20px; }
#bossHpWrap { height: 16px; background: var(--bar-well); border: 1px solid rgba(0, 0, 0, 0.85); overflow: hidden; position: relative; border-radius: var(--r-1); box-shadow: rgba(233, 223, 196, 0.12) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.6) 0px 2px 5px inset, rgba(0, 0, 0, 0.4) 0px 2px; }
#bossHp { position: relative; z-index: 1; height: 100%; width: 100%; background: linear-gradient(rgb(240, 106, 92), rgb(168, 31, 24) 55%, rgb(110, 18, 16)); transition: width 0.18s; }
#bossHp::after { content: ""; position: absolute; left: 0px; right: 0px; top: 0px; height: 48%; background: var(--bar-sheen); pointer-events: none; }
#bossHpChip { position: absolute; z-index: 0; top: 0px; height: 100%; background: rgba(255, 220, 180, 0.5); transition: width 0.5s 0.12s; }
.bossHpTick { position: absolute; z-index: 2; top: -1px; bottom: -1px; width: 2px; margin-left: -1px; background: rgba(247, 229, 190, 0.74); box-shadow: rgba(8, 10, 16, 0.72) 0px 0px 0px 1px, rgba(226, 169, 60, 0.34) 0px 0px 5px; }
.bossHpTick::after { content: ""; position: absolute; left: 50%; top: 50%; width: 5px; height: 5px; transform: translate(-50%, -50%) rotate(45deg); background: rgb(232, 215, 170); border: 1px solid rgba(8, 10, 16, 0.85); }
.bossHpTickTwo { left: 66%; }
.bossHpTickThree { left: 32%; }
#bossStatusRail { display: grid; grid-template-columns: auto minmax(0px, 1fr); align-items: center; gap: 8px; min-height: 22px; margin-top: 3px; padding: 2px 6px; color: rgba(239, 230, 207, 0.76); background: linear-gradient(rgba(19, 23, 34, 0.92), rgba(8, 11, 18, 0.94)); border-width: 1px; border-style: solid; border-color: rgba(233, 223, 196, 0.14) rgba(0, 0, 0, 0.75) rgba(0, 0, 0, 0.75); border-image: none; border-radius: 2px; box-shadow: rgba(255, 255, 255, 0.024) 0px 0px 0px 1px inset; font: 800 8px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.1em; }
#bossPhaseRail { display: flex; align-items: center; gap: 5px; padding-right: 8px; border-right: 1px solid rgba(233, 223, 196, 0.15); white-space: nowrap; }
.bossRailLabel { color: rgba(239, 230, 207, 0.5); font-size: 7px; letter-spacing: 0.16em; }
#bossPhasePips { display: flex; align-items: center; gap: 2px; }
.bossPhasePip { display: block; width: 10px; height: 4px; transform: skew(-18deg); background: rgb(41, 45, 56); border: 1px solid rgba(0, 0, 0, 0.7); box-shadow: rgba(233, 223, 196, 0.06) 0px 0px 0px 1px inset; }
#bossPhaseValue { min-width: 40px; color: rgb(216, 178, 233); font-size: 8px; text-align: left; letter-spacing: 0.06em; }
#bossBreakRail { --boss-break: #e2a93c; display: grid; grid-template-columns: 55px minmax(42px, 1fr) 39px; align-items: center; gap: 6px; min-width: 0px; color: var(--boss-break); }
#bossBreakLabel { text-align: left; font-size: 8px; letter-spacing: 0.14em; text-shadow: rgb(0, 0, 0) 0px 1px 2px; }
#bossBreakTrack { height: 5px; min-width: 0px; overflow: hidden; background: rgb(17, 21, 32); border: 1px solid rgba(0, 0, 0, 0.82); border-radius: 1px; box-shadow: rgba(233, 223, 196, 0.05) 0px 0px 0px 1px inset; }
#bossBreakFill { height: 100%; width: 0px; background: linear-gradient(90deg,color-mix(in srgb,var(--boss-break) 58%,#151923),var(--boss-break)); transform-origin: left center; transition: width 0.08s linear; box-shadow: 0 0 7px color-mix(in srgb,var(--boss-break) 58%,transparent); }
#bossBreakValue { color: rgba(245, 237, 218, 0.82); font-size: 8px; letter-spacing: 0.03em; text-align: right; font-variant-numeric: tabular-nums; }
@keyframes bossExposedPulse { 
  100% { filter: brightness(1.45); box-shadow: 0 0 10px var(--boss-break); }
}
#bossCue { --boss-cue: #e2a93c; display: grid; grid-template-columns: auto minmax(0px, 1fr); align-items: center; gap: 7px; margin: 5px auto 0px; width: max-content; max-width: calc(100% - 18px); padding: 4px 8px; opacity: 0; visibility: hidden; transform: translateY(-5px); color: var(--ink); background: linear-gradient(90deg,color-mix(in srgb,var(--boss-cue) 18%,rgba(9,12,19,.95)),#090c13ed); border-top-color: ; border-top-style: ; border-top-width: ; border-right-color: ; border-right-style: ; border-right-width: ; border-bottom-color: ; border-bottom-style: ; border-bottom-width: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-left: 3px solid var(--boss-cue); box-shadow: rgba(255, 255, 255, 0.05) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.38) 0px 4px 12px; transition: opacity 0.12s, transform 0.12s, visibility 0.12s; pointer-events: none; }
#bossCue strong { color: var(--boss-cue); font: 800 10px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.12em; white-space: nowrap; text-shadow: rgb(0, 0, 0) 0px 1px 2px; }
#bossCue span { min-width: 0px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: rgba(245, 237, 218, 0.82); font: 9px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.035em; }
@keyframes bossCueArrive { 
  0% { opacity: 0.2; transform: translateY(-6px) scale(0.98); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}
@keyframes bossCueStrike { 
  0% { filter: brightness(1.85); transform: scale(1.035); }
  100% { filter: brightness(1); transform: scale(1); }
}
@media (max-width: 720px) {#bossCue { grid-template-columns: 1fr; gap: 1px; } #bossCue span { font-size: 8px; } #bossStatusRail { gap: 6px; } #bossPhaseRail { gap: 4px; padding-right: 6px; } #bossBreakRail { grid-template-columns: 52px minmax(34px, 1fr) 36px; gap: 4px; }}
#mapWrap { bottom: 14px; right: 14px; padding: 7px; pointer-events: auto; cursor: pointer; color: inherit; font: inherit; text-align: inherit; appearance: none; background: linear-gradient(rgba(37, 44, 65, 0.94), rgba(19, 23, 36, 0.96)); border: 1px solid rgba(0, 0, 0, 0.85); border-radius: 5px; box-shadow: rgba(233, 223, 196, 0.14) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.5) 0px 3px, rgba(0, 0, 0, 0.5) 0px 10px 26px; transition: transform 0.12s, box-shadow 0.12s; }
#mapWrap:hover { transform: translateY(-2px); box-shadow: rgba(233, 223, 196, 0.3) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.5) 0px 5px, rgba(0, 0, 0, 0.55) 0px 13px 30px; }
#mapWrap:focus-visible { outline: 2px solid var(--copper); outline-offset: 3px; }
#map { display: block; width: 126px; height: 126px; image-rendering: pixelated; background: rgb(13, 17, 25); border: 1px solid rgba(0, 0, 0, 0.8); border-radius: 3px; }
#mapMeta { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 6px; }
#mapLabel { min-width: 0px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#mapKey { font: 9px ui-monospace, Menlo, Consolas, monospace; color: var(--chalk); border: 1px solid var(--edge); border-radius: 2px; padding: 0px 4px; background: rgba(0, 0, 0, 0.35); }
#mapWaypointMeta { display: flex; align-items: center; gap: 5px; max-width: 126px; margin-top: 4px; font: 700 9px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.06em; color: rgb(174, 239, 255); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#mapWaypointMeta[hidden] { display: none; }
#mapClock { display: flex; align-items: baseline; justify-content: space-between; gap: 6px; max-width: 126px; margin-top: 4px; }
#mapClock #clockTime { font: 700 11px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.08em; color: rgb(233, 223, 196); text-shadow: rgb(5, 8, 6) 0px 1px 0px; }
#mapClock #clockPhase { font: 700 8px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.14em; color: rgba(233, 223, 196, 0.55); }
#mapWaypointMeta i { width: 7px; height: 7px; flex: 0 0 7px; background: rgb(115, 229, 255); border: 1px solid rgba(5, 7, 11, 0.8); transform: rotate(45deg); box-shadow: rgba(115, 229, 255, 0.8) 0px 0px 8px; }
#mapNorth { position: absolute; z-index: 1; top: 10px; left: 50%; transform: translate(-50%); font: 700 8px ui-monospace, Menlo, Consolas, monospace; color: rgba(245, 237, 218, 0.9); text-shadow: rgb(0, 0, 0) 0px 1px 2px; pointer-events: none; }
#mapForecast { display: flex; align-items: center; justify-content: space-between; gap: 6px; padding: 0px 2px; margin-top: 2px; }
#mapForecast .eyebrow { font: 700 8px ui-monospace, Menlo, Consolas, monospace; letter-spacing: 0.14em; color: rgb(127, 143, 156); opacity: 0.8; }
#forecastPips { display: flex; align-items: flex-end; gap: 3px; height: 11px; }
.fcPip { display: block; width: 5px; height: 3px; border-radius: 1px; background: rgb(92, 107, 120); transition: height 0.5s, background-color 0.5s; opacity: 0.9; }
@starting-style {
  #worldMap.show { opacity: 0; }
}
@keyframes mapIn { 
  0% { opacity: 0; transform: translateY(10px) scale(0.985); }
}
@supports (width:1cqw) {
  #worldMapStage { width: min(100cqw - 12px, 100cqh - 12px, 1024px); }
}
